findings.codeql_raw_query:
/**
 * @name Type confusion vulnerabilities
 * @description Type confusion through improper isinstance checks or type comparisons
 * @kind problem
 * @problem.severity warning
 * @id py/type-confusion
 * @tags security
 *        external/cwe/cwe-843
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module TypeConfusionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call call |
      call.getFunc().(Name).getId() = "isinstance" and
      sink = DataFlow::exprNode(call.getArg(1))
    )
  }
}

module TypeConfusionFlow = TaintTracking::Global<TypeConfusionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where TypeConfusionFlow::flow(source, sink)
select sink, "User input flows to isinstance type argument, potentially causing type confusion."
